"use strict";
/*
 * Differential test: the EVM implementation of Addr (contracts/Poseidon2b.sol) against vectors
 * produced by the VENDOR Parano1d crate (noid_poseidon2b::primitives::derive_address), not by the
 * JavaScript port or the portable Rust spec.
 *
 *   test/vectors/addr-vectors.bin  = 64 bytes per vector: secret (32) || Addr(secret) (32)
 *   generated by:  equiv-ref addr-vectors test/vectors/addr-vectors.bin   (see eth/README.md)
 *   layout:        299 structured secrets (index 0..298; the 256 single-bit secrets are 43..298),
 *                  then 12,000 seeded-random ones (secret i = SHA-256("<seed>|<i>")).
 *
 * What runs:
 *   default                  the file is checked (size, checksum, secrets regenerated here); the JS port is
 *                            compared with the vendor on the selected vectors; the EVM is compared with the
 *                            vendor on the selected vectors = all 299 structured (incl. the 256 single-bit
 *                            ones) + 300 random ones (every 40th).
 *   POSEIDON_VECTORS=all     every vector of the slice [POSEIDON_START, POSEIDON_START + POSEIDON_COUNT)
 *                            (defaults: 0 and the rest of the file), for the EVM AND for the JS port.
 *
 * Nothing is skipped or shrunk: a machine that cannot hold the run fails with a message
 * (test/helpers/chain-budget.js recycles the Hardhat chain every few dozen calls because the EDR
 * runtime retains a trace per call). Each mismatch is reported with its index and secret.
 */
const { expect } = require("chai");
const { ethers } = require("hardhat");
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const P = require("../scripts/poseidon/poseidon2b.js");
const { createChainBudget } = require("./helpers/chain-budget.js");

const VEC_FILE = path.resolve(__dirname, "vectors/addr-vectors.bin");
const SUM_FILE = path.resolve(__dirname, "vectors/addr-vectors.bin.sha256");
const SEED = "noid-swap/poseidon2b/addr-vectors/v1";
const N_STRUCTURED = 299;
const N_RANDOM = 12000;
const BATCH = Number(process.env.POSEIDON_BATCH || 1); // secrets per eth_call. Keep 1: a multi-permutation eth_call crashed the Hardhat runtime (segmentation fault) in a full-suite run after live.test.js
const ALL = process.env.POSEIDON_VECTORS === "all";
const hex = (b) => "0x" + Buffer.from(b).toString("hex");

/** The structured secrets, in the order of equiv/reference (structured_secrets). */
function structuredSecrets() {
  const v = [Buffer.alloc(32), Buffer.alloc(32, 0xff), Buffer.from([...Array(32).keys()])];
  for (const b of [0x80, 0xe0, 0x01, 0x7f, 0xaa, 0x55]) v.push(Buffer.alloc(32, b));
  const lo = Buffer.alloc(32);
  lo.fill(0xff, 0, 16);
  const hi = Buffer.alloc(32);
  hi.fill(0xff, 16, 32);
  v.push(lo, hi);
  for (let i = 0; i < 32; i++) {
    const s = Buffer.alloc(32);
    s[i] = 0xff;
    v.push(s);
  }
  for (let k = 0; k < 256; k++) {
    const s = Buffer.alloc(32);
    s[k >> 3] = 1 << (k & 7);
    v.push(s);
  }
  return v;
}
const randomSecret = (i) => crypto.createHash("sha256").update(`${SEED}|${i}`).digest();

const raw = fs.readFileSync(VEC_FILE);
const total = raw.length / 64;
const secretAt = (i) => raw.subarray(i * 64, i * 64 + 32);
const addrAt = (i) => raw.subarray(i * 64 + 32, i * 64 + 64);

// ---- which vectors this run covers ------------------------------------------------------------
let indices;
if (ALL) {
  const start = Number(process.env.POSEIDON_START || 0);
  const count = process.env.POSEIDON_COUNT !== undefined ? Number(process.env.POSEIDON_COUNT) : total - start;
  indices = [];
  for (let i = start; i < Math.min(total, start + count); i++) indices.push(i);
} else {
  indices = [...Array(N_STRUCTURED).keys()];
  for (let k = 0; k < 300; k++) indices.push(N_STRUCTURED + 40 * k);
}

// The JavaScript port is compared with the vendor vectors in small steps that hand the event loop back every few
// milliseconds: one long synchronous computation (seconds) while the Hardhat runtime (EDR) exists made the next
// provider call crash the Node process with a segmentation fault, in a full-suite run.
const yieldLoop = () => new Promise((resolve) => setImmediate(resolve));
async function compareJsPort() {
  const bad = [];
  for (let n = 0; n < indices.length; n++) {
    const i = indices[n];
    if (!P.addr(secretAt(i)).equals(addrAt(i))) bad.push(i);
    if (n % 8 === 7) await yieldLoop();
  }
  return bad;
}

describe("Poseidon2b EVM vs vendor vectors (equiv-ref addr-vectors)", function () {
  this.timeout(3600000);

  let H = null;
  const chain = createChainBudget(ethers, {
    what: "Poseidon2b vector test",
    onRecycle: () => {
      H = null;
    },
    probe: async (n) => {
      if (!H) H = await (await ethers.getContractFactory("Poseidon2bHarness")).deploy();
      for (let i = 0; i < n; i++) await H.addr(hex(secretAt(2)));
    },
  });
  const harness = async (perms) => {
    await chain.budget(perms);
    if (!H) H = await (await ethers.getContractFactory("Poseidon2bHarness")).deploy();
    return H;
  };

  after(async () => {
    await chain.recycle();
  });

  it("the selected range covers at least one vector (an empty slice would pass every comparison for nothing)", () => {
    expect(total, "the vectors file is empty").to.be.greaterThan(0);
    expect(indices.length, "POSEIDON_START / POSEIDON_COUNT select no vector (or are not numbers)").to.be.greaterThan(0);
    for (const i of indices) expect(Number.isInteger(i) && i >= 0 && i < total, `vector index ${i} is outside the file`).to.equal(true);
  });

  it("the vectors file is intact and its secrets are the documented ones", () => {
    expect(raw.length % 64, "file size must be a multiple of 64").to.equal(0);
    expect(total).to.equal(N_STRUCTURED + N_RANDOM);
    const sum = crypto.createHash("sha256").update(raw).digest("hex");
    const recorded = fs.readFileSync(SUM_FILE, "utf8").trim().split(/\s+/)[0];
    expect(sum, "addr-vectors.bin does not match addr-vectors.bin.sha256").to.equal(recorded);
    const st = structuredSecrets();
    expect(st.length).to.equal(N_STRUCTURED);
    for (let i = 0; i < N_STRUCTURED; i++) if (!secretAt(i).equals(st[i])) expect.fail(`structured secret #${i} differs`);
    for (let i = 0; i < N_RANDOM; i += 1) {
      if (!secretAt(N_STRUCTURED + i).equals(randomSecret(i))) expect.fail(`random secret #${i} is not SHA-256("${SEED}|${i}")`);
    }
    // the published vector (docs/parano1d-capabilities.md section 10) is vector 2
    expect(secretAt(2).toString("hex")).to.equal("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
    expect(addrAt(2).toString("hex")).to.equal("f8183db204ffb765c7015d851c1754e4974c675b975c6738d9f6d138eb7212cf");
    // all-zero secret has an address that is not all zero, and no two vectors share an address
    const seen = new Set();
    for (let i = 0; i < total; i++) {
      const k = addrAt(i).toString("hex");
      if (seen.has(k)) expect.fail(`address of vector #${i} repeats`);
      seen.add(k);
    }
  });

  it(`the JavaScript port (the fuzz model's Addr) equals the vendor on ${indices.length} vectors`, async () => {
    const t0 = Date.now();
    const bad = await compareJsPort();
    console.log(`        JS port vs vendor: ${indices.length} vectors compared in ${((Date.now() - t0) / 1000).toFixed(1)} s, ${bad.length} mismatches`);
    expect(bad, `JS port differs from the vendor on vectors ${bad.slice(0, 20)}`).to.deep.equal([]);
  });

  it(`the EVM contract equals the vendor on ${indices.length} vectors (${ALL ? "slice " + indices[0] + ".." + indices[indices.length - 1] : "299 structured incl. 256 single-bit, + 300 random"})`, async () => {
    const t0 = Date.now();
    const bad = [];
    for (let at = 0; at < indices.length; at += BATCH) {
      const idx = indices.slice(at, at + BATCH);
      const h = await harness(idx.length);
      const got = await h.addrMany(idx.map((i) => hex(secretAt(i))));
      idx.forEach((i, j) => {
        if (got[j] !== hex(addrAt(i))) bad.push({ i, secret: hex(secretAt(i)), want: hex(addrAt(i)), got: got[j] });
      });
      if (bad.length > 20) break;
    }
    console.log(
      `        EVM vs vendor: ${indices.length} vectors checked, ${bad.length} mismatches, ${((Date.now() - t0) / 1000).toFixed(1)} s, ` +
        `chain recycled ${chain.mem.recycles}x in chunks of ${chain.mem.chunk}` +
        (ALL ? ` (slice ${indices[0]}..${indices[indices.length - 1]} of ${total})` : "")
    );
    expect(bad, "EVM Addr differs from the vendor Addr: " + JSON.stringify(bad.slice(0, 5))).to.deep.equal([]);
  });
});
